const express = require('express');
const crypto = require('crypto');
const expressWs = require('express-ws')(express());
const app = expressWs.app;
const port = process.env.PORT || 3000;

app.use(express.json());

let subscribers = {};
let wsClients = new Set();

app.post('/subscribe', (req, res) => {
  const subId = crypto.randomUUID();
  subscribers[subId] = { notifications: [] };
  res.status(201).json({ subId });
});

app.post('/notify', (req, res) => {
  const { message } = req.body;
  Object.values(subscribers).forEach(sub => sub.notifications.push(message));
  wsClients.forEach(ws => ws.send(JSON.stringify({ type: 'notification', message })));
  res.json({ notified: Object.keys(subscribers).length });
});

app.get('/notifications/:subId', (req, res) => {
  const sub = subscribers[req.params.subId];
  if (!sub) return res.status(404).json({ error: 'Subscriber not found' });
  res.json({ notifications: sub.notifications });
});

app.ws('/ws', (ws, req) => {
  wsClients.add(ws);
  ws.on('close', () => wsClients.delete(ws));
});

