package main

import (
	"encoding/json"
	"net/http"
	"os"
	"strings"
	"sync"

	"github.com/google/uuid"
	"github.com/gorilla/websocket"
)

type Subscriber struct {
	Notifications []string `json:"notifications"`
}

var (
	subscribers = make(map[string]*Subscriber)
	wsClients   = make(map[*websocket.Conn]bool)
	mu          sync.Mutex
	upgrader    = websocket.Upgrader{CheckOrigin: func(r *http.Request) bool { return true }}
)

func main() {
	port := os.Getenv("PORT")
	if port == "" {
		port = "3000"
	}

	http.HandleFunc("/subscribe", func(w http.ResponseWriter, r *http.Request) {
		subID := uuid.New().String()
		subscribers[subID] = &Subscriber{Notifications: []string{}}
		w.Header().Set("Content-Type", "application/json")
		w.WriteHeader(http.StatusCreated)
		json.NewEncoder(w).Encode(map[string]string{"subId": subID})
	})

	http.HandleFunc("/notify", func(w http.ResponseWriter, r *http.Request) {
		var body struct {
			Message string `json:"message"`
		}
		json.NewDecoder(r.Body).Decode(&body)
		for _, sub := range subscribers {
			sub.Notifications = append(sub.Notifications, body.Message)
		}
		mu.Lock()
		for conn := range wsClients {
			data, _ := json.Marshal(map[string]string{"type": "notification", "message": body.Message})
			conn.WriteMessage(websocket.TextMessage, data)
		}
		mu.Unlock()
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]int{"notified": len(subscribers)})
	})

	http.HandleFunc("/notifications/", func(w http.ResponseWriter, r *http.Request) {
		subID := strings.TrimPrefix(r.URL.Path, "/notifications/")
		sub, ok := subscribers[subID]
		if !ok {
			w.Header().Set("Content-Type", "application/json")
			w.WriteHeader(http.StatusNotFound)
			json.NewEncoder(w).Encode(map[string]string{"error": "Subscriber not found"})
			return
		}
		w.Header().Set("Content-Type", "application/json")
		json.NewEncoder(w).Encode(map[string]interface{}{"notifications": sub.Notifications})
	})

	http.HandleFunc("/ws", func(w http.ResponseWriter, r *http.Request) {
		conn, _ := upgrader.Upgrade(w, r, nil)
		mu.Lock()
		wsClients[conn] = true
		mu.Unlock()
		defer func() {
			mu.Lock()
			delete(wsClients, conn)
			mu.Unlock()
			conn.Close()
		}()
		for {
			_, _, _ = conn.ReadMessage()
		}
	})

	http.ListenAndServe(":"+port, nil)
}
